<script setup lang="ts">
import { computed, onBeforeUnmount, ref, shallowRef } from 'vue';
import { api, get } from '../services/api';
import { usePolling } from '../composables/usePolling';
import { storeToRefs } from 'pinia';
import { useSettings } from '../stores/settings';
const utcDateDaysAgo = (days: number) => new Date(Date.now() - days * 86_400_000).toISOString().slice(0, 10);
const latestSafeDate = utcDateDaysAgo(1);
const leaderboard=shallowRef<any>({data:[]}); const experiments=shallowRef<any>({data:[],last_page:1}); const daily=shallowRef<any>({data:[]}); const page=ref(1); const error=ref(''); const notice=ref(''); const queuing=ref(false); const {timezone}=storeToRefs(useSettings());
const form=ref({strategy_id:'trend_pullback',symbols:['BTCUSDT','ETHUSDT'],from:utcDateDaysAgo(15),to:latestSafeDate,evaluation_mode:'split'});
const hasActiveExperiments=computed(()=>(experiments.value.data||[]).some((row:any)=>['QUEUED','RUNNING','CANCEL_REQUESTED'].includes(row.status)));
const hasEvaluatedStrategy=computed(()=>(leaderboard.value.data||[]).some((row:any)=>row.metrics!==null));
const canQueue=computed(()=>form.value.symbols.length>0&&form.value.from<form.value.to&&form.value.to<=latestSafeDate);
let controller:AbortController|undefined;
const load=async()=>{ controller?.abort(); controller=new AbortController(); try { const zone=timezone.value==='local'?Intl.DateTimeFormat().resolvedOptions().timeZone:timezone.value; const [leaders,runs,performance]=await Promise.all([get<any>('/research/leaderboard',undefined,controller.signal),get<any>('/research/experiments',{page:page.value,per_page:10},controller.signal),get<any>('/research/daily-performance',{per_page:10,timezone:zone},controller.signal)]); leaderboard.value=leaders; experiments.value=runs; daily.value=performance; error.value=''; } catch(e:any){ if(e.name!=='CanceledError')error.value=e.message; throw e; } };
const {loading,refresh}=usePolling(load,10000,hasActiveExperiments); onBeforeUnmount(()=>controller?.abort());
const queue=async()=>{ queuing.value=true; notice.value=''; try { const response=await api.post('/research/experiments',form.value); notice.value=`Experiment ${response.data.data.id} queued. A dedicated worker runs it asynchronously; this page refreshes while it is active.`; await refresh(); } catch(e:any){error.value=e.message;} finally{queuing.value=false;} };
const action=async(id:string,name:'cancel'|'approve-forward')=>{ try { await api.post(`/research/experiments/${id}/${name}`); await refresh(); } catch(e:any){error.value=e.message;} };
</script>
<template><q-page padding>
  <div class="page-title"><div><span class="eyebrow">STRATEGY RESEARCH LAB</span><h1>Robustness Before Return</h1></div></div>
  <q-banner class="bg-grey-9 text-white q-mb-md">Historical research and isolated forward-paper results only. No strategy is presented as profitable without sufficient out-of-sample evidence.</q-banner>
  <q-banner v-if="error" class="bg-negative text-white q-mb-md">{{error}} <q-btn flat label="Retry" @click="refresh" /></q-banner>
  <q-banner v-if="notice" class="bg-positive text-white q-mb-md">{{notice}}</q-banner>
  <q-banner v-if="hasActiveExperiments" class="bg-blue-grey-9 text-white q-mb-md">A research experiment is queued or running asynchronously. The dedicated worker processes one heavy research job at a time; results refresh automatically about every 10 seconds.</q-banner>
  <q-banner class="bg-blue-grey-10 text-white q-mb-md">All enabled strategies use the same closed-candle hierarchy: 1h trend · 30m setup · 15m entry · 5m confirmation. Results remain separate by strategy version and are never combined with forward-paper performance.</q-banner>
  <section><h2>Strategy Leaderboard</h2><q-table flat bordered :loading="loading" :rows="leaderboard.data||[]" row-key="id" :pagination="{rowsPerPage:0}" hide-pagination :columns="[
    {name:'id',label:'Strategy',field:'id',align:'left'},{name:'return',label:'OOS Net PnL',field:(r:any)=>r.metrics?.net_pnl??'Not evaluated'},
    {name:'pf',label:'Profit Factor',field:(r:any)=>r.metrics?.profit_factor??'—'},{name:'dd',label:'Max DD',field:(r:any)=>r.metrics?.maximum_drawdown_percent??'—'},
    {name:'trades',label:'Trades',field:(r:any)=>r.metrics?.total_trades??0},{name:'status',label:'Status',field:(r:any)=>r.ranking?.status??'NOT_EVALUATED'}]" /><div v-if="!loading&&!hasEvaluatedStrategy" class="muted q-pa-md"><b>NOT_EVALUATED</b> means no experiment for the current strategy version has completed with out-of-sample metrics. Automatic research first collects a complete 14-day evaluation window plus indicator warm-up, then queues each strategy on the dedicated worker. Queued or running jobs do not populate the leaderboard.</div></section>
  <section><h2>Queue Bounded Experiment</h2><q-card flat bordered class="form panel"><q-select v-model="form.strategy_id" :options="['baseline','trend_pullback','bollinger_mean_reversion','donchian_atr_breakout','regime_switching','momentum','support_resistance_bounce','support_resistance_breakout']" label="Strategy"/><q-select v-model="form.symbols" multiple :options="['BTCUSDT','ETHUSDT']" label="Symbols"/><q-input v-model="form.from" type="date" label="From" :max="latestSafeDate"/><q-input v-model="form.to" type="date" label="To" :max="latestSafeDate"/><q-select v-model="form.evaluation_mode" :options="['split','walk_forward']" label="Evaluation"/><div class="muted">Pre-filled with the last 14 complete UTC days for a quick bounded run. Split mode is faster; walk-forward gives stronger but slower evidence.</div><q-btn color="primary" :loading="queuing" :disable="!canQueue" label="Queue research experiment" @click="queue"/></q-card></section>
  <section><h2>Experiments · 10 per page</h2><q-table flat bordered :rows="experiments.data||[]" row-key="id" :pagination="{rowsPerPage:0}" hide-pagination :columns="[{name:'strategy',label:'Strategy',field:'strategy_id',align:'left'},{name:'mode',label:'Mode',field:'evaluation_mode'},{name:'status',label:'Status',field:'status'},{name:'created',label:'Created',field:'created_at'},{name:'actions',label:'Deliberate action',field:'id'}]"><template #body-cell-actions="props"><q-td :props="props"><q-btn v-if="['QUEUED','RUNNING'].includes(props.row.status)" flat color="warning" label="Cancel" @click="action(props.row.id,'cancel')"/><q-btn v-if="props.row.status==='COMPLETED'" flat color="positive" label="Approve forward paper" @click="action(props.row.id,'approve-forward')"/></q-td></template></q-table><div v-if="!loading&&!(experiments.data||[]).length" class="muted q-pa-md">Automatic bootstrap is collecting the required closed-candle history. It will queue all current strategies when the complete evaluation and warm-up window is ready. For the quickest diagnostic result, you can also use the protected form above with one symbol in split mode.</div><q-pagination v-model="page" :max="experiments.last_page||1" @update:model-value="refresh" /></section>
  <section><h2>Isolated Forward-Paper Daily Performance</h2><q-table flat bordered :rows="daily.data||[]" row-key="account.id" :pagination="{rowsPerPage:0}" hide-pagination :columns="[{name:'strategy',label:'Strategy',field:(r:any)=>r.account.strategy_id,align:'left'},{name:'today',label:'Today',field:(r:any)=>r.performance.today.net_pnl??'Incomplete'},{name:'yesterday',label:'Yesterday',field:(r:any)=>r.performance.yesterday.net_pnl??'Incomplete'},{name:'week',label:'Last 7 Days',field:(r:any)=>r.performance.last_7_days.net_pnl??'Incomplete'},{name:'month',label:'Last 30 Days',field:(r:any)=>r.performance.last_30_days.net_pnl??'Incomplete'},{name:'equity',label:'Equity',field:(r:any)=>r.account.current_equity}]"/><div v-if="!daily.data?.length" class="muted q-pa-md">No approved research forward-paper portfolios. No performance is fabricated.</div></section>
</q-page></template>
